// Check how many documents need embeddings
const POSTGREST = $env.POSTGREST_URL;
const JWT = $env.POSTGREST_JWT;

// Fetch legal_documents without embeddings
const resp = await $http.request({
  method: 'GET',
  url: `${POSTGREST}/legal_documents?select=id,supplier_id,doc_type,status,content,created_at&order=created_at.desc&limit=50`,
  headers: { Authorization: `Bearer ${JWT}`, Accept: 'application/json' }
});
const docs = resp;

// Check which ones already have embeddings
const existResp = await $http.request({
  method: 'GET',
  url: `${POSTGREST}/document_embeddings?select=source_id&doc_type=eq.legal_document&limit=500`,
  headers: { Authorization: `Bearer ${JWT}`, Accept: 'application/json' }
});
const existingIds = new Set(existResp.map(e => e.source_id));

const toEmbed = docs.filter(d => !existingIds.has(d.id));
console.log(`Legal docs to embed: ${toEmbed.length} / ${docs.length}`);

// Also fetch contracts
const contractResp = await $http.request({
  method: 'GET',
  url: `${POSTGREST}/contracts?select=id,supplier_id,name,category,terms_summary,value,currency,expiry_date,renewal_state&order=created_at.desc&limit=100`,
  headers: { Authorization: `Bearer ${JWT}`, Accept: 'application/json' }
});

const existContractResp = await $http.request({
  method: 'GET',
  url: `${POSTGREST}/document_embeddings?select=source_id&doc_type=eq.contract&limit=500`,
  headers: { Authorization: `Bearer ${JWT}`, Accept: 'application/json' }
});
const existContractIds = new Set(existContractResp.map(e => e.source_id));

const contractsToEmbed = contractResp.filter(c => !existContractIds.has(c.id) && c.terms_summary);
console.log(`Contracts to embed: ${contractsToEmbed.length}`);

// Also fetch policies
const policyResp = await $http.request({
  method: 'GET',
  url: `${POSTGREST}/rag_policies?select=id,title,category,content&limit=20`,
  headers: { Authorization: `Bearer ${JWT}`, Accept: 'application/json' }
});

const existPolicyResp = await $http.request({
  method: 'GET',
  url: `${POSTGREST}/document_embeddings?select=source_id&doc_type=eq.policy&limit=100`,
  headers: { Authorization: `Bearer ${JWT}`, Accept: 'application/json' }
});
const existPolicyIds = new Set(existPolicyResp.map(e => e.source_id));
const policiesToEmbed = policyResp.filter(p => !existPolicyIds.has(p.id));
console.log(`Policies to embed: ${policiesToEmbed.length}`);

// Combine all work items
const workItems = [
  ...toEmbed.map(d => ({
    type: 'legal_document',
    source_id: d.id,
    supplier_id: d.supplier_id,
    text: `${d.doc_type.toUpperCase()}: ${d.content}`,
    meta_title: `${d.doc_type.toUpperCase()} - ${d.status}`,
    meta_category: d.doc_type,
    meta_status: d.status,
    meta_tags: [d.doc_type, d.status]
  })),
  ...contractsToEmbed.map(c => ({
    type: 'contract',
    source_id: c.id,
    supplier_id: c.supplier_id,
    text: `CONTRACT: ${c.name}\nCategory: ${c.category}\nValue: ${c.value} ${c.currency}\nExpiry: ${c.expiry_date}\nRenewal state: ${c.renewal_state}\nTerms: ${c.terms_summary}`,
    meta_title: c.name,
    meta_category: c.category,
    meta_status: c.renewal_state,
    meta_tags: [c.category, c.renewal_state, c.currency]
  })),
  ...policiesToEmbed.map(p => ({
    type: 'policy',
    source_id: p.id,
    supplier_id: null,
    text: `POLICY: ${p.title}\n${p.content}`,
    meta_title: p.title,
    meta_category: p.category,
    meta_status: 'active',
    meta_tags: [p.category, 'policy']
  }))
];

console.log(`Total items to embed: ${workItems.length}`);
return workItems.map(item => ({ json: item }));

// Batch into groups of 5 to avoid rate limits
const items = $input.all();
const batches = [];
for (let i = 0; i < items.length; i += 5) {
  batches.push(items.slice(i, i + 5));
}
console.log(`Processing ${items.length} items in ${batches.length} batches`);
// Return first batch (loop handles rest via SplitInBatches)
return items;

// Extract embedding from OpenAI response and build insert record
const embedding = $json.data[0].embedding;
const item = $('Prepare Batches').item.json;

return [{
  json: {
    doc_type: item.type,
    source_id: item.source_id,
    supplier_id: item.supplier_id,
    chunk_index: 0,
    chunk_text: item.text.substring(0, 4000),
    embedding: JSON.stringify(embedding),  // PostgREST accepts stringified vector
    meta_title: item.meta_title,
    meta_category: item.meta_category,
    meta_status: item.meta_status,
    meta_tags: item.meta_tags
  }
}];

// Log summary
const all = $input.all();
console.log(`RAG embedder run complete. Processed ${all.length} items.`);
return [{ json: { status: 'done', processed: all.length, timestamp: new Date().toISOString() } }];
